29	namespace atb {
30	AclnnMatmulGetWorkspaceSizeFunc LinearAclnnRunner::aclnnMatmulGetWorkspaceSizeFunc_ = nullptr;
31	AclnnMatmulExecuteFunc LinearAclnnRunner::aclnnMatmulExecuteFunc_ = nullptr;
32	AclnnAddmmGetWorkspaceSizeFunc LinearAclnnRunner::aclnnAddmmGetWorkspaceSizeFunc_ = nullptr;
33	AclnnAddmmExecuteFunc LinearAclnnRunner::aclnnAddmmExecuteFunc_ = nullptr;
34	AclnnMatmulWeightNzGetWorkspaceSizeFunc LinearAclnnRunner::aclnnMatmulWeightNzGetWorkspaceSizeFunc_ = nullptr;
35	AclnnMatmulWeightNzExecuteFunc LinearAclnnRunner::aclnnMatmulWeightNzExecuteFunc_ = nullptr;
36	AclnnAddmmWeightNzGetWorkspaceSizeFunc LinearAclnnRunner::aclnnAddmmWeightNzGetWorkspaceSizeFunc_ = nullptr;
37	AclnnAddmmWeightNzExecuteFunc LinearAclnnRunner::aclnnAddmmWeightNzExecuteFunc_ = nullptr;
38	AclnnBatchMatMulWeightNzGetWorkspaceSizeFunc LinearAclnnRunner::aclnnBatchMatMulWeightNzGetWorkspaceSizeFunc_ = nullptr;
39	AclnnBatchMatMulWeightNzExecuteFunc LinearAclnnRunner::aclnnBatchMatMulWeightNzExecuteFunc_ = nullptr;
40	
41	LinearAclnnRunner::LinearAclnnRunner(const infer::LinearParam &param) : AclnnRunner("LinearAclnnRunner"), param_(param)
42	{
43	    ATB_LOG(INFO) << GetLogPrefix() << "LinearAclnnRunner::LinearAclnnRunner";
44	
45	    GetTensorNum();
46	}
47	
48	LinearAclnnRunner::~LinearAclnnRunner()
49	{
50	    if (alpha_) {
51	        if (aclDestroyScalar(alpha_) != ACL_SUCCESS) {
52	            ATB_LOG(ERROR) << GetLogPrefix() << "alpha aclDestroyScalar error";
53	        }
54	        alpha_ = nullptr;
55	    }
56	    if (beta_) {
57	        if (aclDestroyScalar(beta_) != ACL_SUCCESS) {
58	            ATB_LOG(ERROR) << GetLogPrefix() << "beta aclDestroyScalar error";
59	        }
60	        beta_ = nullptr;
61	    }
62	}
63	
64	Status LinearAclnnRunner::LoadAclnnFuncs()
65	{
66	    ATB_LOG(INFO) << "LinearAclnnRunner::LoadAclnnFuncs";
67	    if ((aclnnMatmulGetWorkspaceSizeFunc_ && aclnnMatmulExecuteFunc_) &&
68	        (aclnnAddmmGetWorkspaceSizeFunc_ && aclnnAddmmExecuteFunc_) &&
69	        (aclnnMatmulWeightNzGetWorkspaceSizeFunc_ && aclnnMatmulWeightNzExecuteFunc_) &&
70	        (aclnnAddmmWeightNzGetWorkspaceSizeFunc_ && aclnnAddmmWeightNzExecuteFunc_) &&
71	        (aclnnBatchMatMulWeightNzGetWorkspaceSizeFunc_ && aclnnBatchMatMulWeightNzExecuteFunc_)) {
72	        return NO_ERROR;
73	    }
74	    Status st = NO_ERROR;
75	    if (!aclnnMatmulGetWorkspaceSizeFunc_ || !aclnnMatmulExecuteFunc_) {
76	        st = LoadFromSharedObjectFile("aclnnMatmulGetWorkspaceSize", "aclnnMatmul", aclnnMatmulGetWorkspaceSizeFunc_,
77	                                      aclnnMatmulExecuteFunc_);
78	        if (st != NO_ERROR) {
79	            return st;
80	        }
81	    }
82	    if (!aclnnAddmmGetWorkspaceSizeFunc_ || !aclnnAddmmExecuteFunc_) {
83	        st = LoadFromSharedObjectFile("aclnnAddmmGetWorkspaceSize", "aclnnAddmm", aclnnAddmmGetWorkspaceSizeFunc_,
84	                                      aclnnAddmmExecuteFunc_);
85	        if (st != NO_ERROR) {
86	            return st;
87	        }
88	    }
89	    if (!aclnnMatmulWeightNzGetWorkspaceSizeFunc_ || !aclnnMatmulWeightNzExecuteFunc_) {
90	        st = LoadFromSharedObjectFile("aclnnMatmulWeightNzGetWorkspaceSize", "aclnnMatmulWeightNz",
91	                                      aclnnMatmulWeightNzGetWorkspaceSizeFunc_, aclnnMatmulWeightNzExecuteFunc_);
92	        if (st != NO_ERROR) {
93	            return st;
94	        }
95	    }
96	    if (!aclnnAddmmWeightNzGetWorkspaceSizeFunc_ || !aclnnAddmmWeightNzExecuteFunc_) {
97	        st = LoadFromSharedObjectFile("aclnnAddmmWeightNzGetWorkspaceSize", "aclnnAddmmWeightNz",
98	                                      aclnnAddmmWeightNzGetWorkspaceSizeFunc_, aclnnAddmmWeightNzExecuteFunc_);
99	        if (st != NO_ERROR) {
100	            return st;
101	        }
102	    }
103	    if (!aclnnBatchMatMulWeightNzGetWorkspaceSizeFunc_ || !aclnnBatchMatMulWeightNzExecuteFunc_) {
104	        st = LoadFromSharedObjectFile("aclnnBatchMatMulWeightNzGetWorkspaceSize", "aclnnBatchMatMulWeightNz",
105	                                      aclnnBatchMatMulWeightNzGetWorkspaceSizeFunc_,
106	                                      aclnnBatchMatMulWeightNzExecuteFunc_);
107	        if (st != NO_ERROR) {
108	            return st;
109	        }
110	    }
111	    return NO_ERROR;
112	}
113	
114	Status LinearAclnnRunner::BuildAclnnVariantPack(const RunnerVariantPack &runnerVariantPack)
115	{
116	    ATB_LOG(INFO) << GetLogPrefix()
117	                  << "LinearAclnnRunner::BuildAclnnVariantPack, runnerVariantPack: " << runnerVariantPack.ToString();
118	    atbVariantPack_ = runnerVariantPack;
119	    isWeightNz_ = runnerVariantPack.inTensors[1].desc.format == ACL_FORMAT_FRACTAL_NZ;
120	    isBatch_ = runnerVariantPack.inTensors[1].desc.shape.dimNum == 3 ||
121	               (runnerVariantPack.inTensors[1].desc.shape.dimNum == 4 &&
122	                runnerVariantPack.inTensors[1].desc.shape.dims[0] != 1);
123	    InitTensorIndex();
124	    aclnnVariantPack_.aclInTensors.reserve(aclInTensorNum_);
125	    aclnnVariantPack_.aclInTensors.resize(aclInTensorNum_);
126	    aclnnVariantPack_.aclOutTensors.reserve(aclOutTensorNum_);
127	    aclnnVariantPack_.aclOutTensors.resize(aclOutTensorNum_);
128	    Status st = NO_ERROR;
129	    if (param_.hasBias) {
130	        st = CreateAddmmMat1AclnnTensor();
131	        if (st != NO_ERROR) {
132	            return st;
133	        }
134	        st = CreateAddmmMat2AclnnTensor();
135	        if (st != NO_ERROR) {
136	            return st;
137	        }
138	        st = CreateAddmmSelfAclnnTensor();
139	        if (st != NO_ERROR) {
140	            return st;
141	        }
142	        st = CreateAddmmOutAclnnTensor();
143	        if (st != NO_ERROR) {
144	            return st;
145	        }
146	    } else {
147	        st = CreateMatmulSelfAclnnTensor();
148	        if (st != NO_ERROR) {
149	            return st;
150	        }
151	        st = CreateMatmulMat2AclnnTensor();
152	        if (st != NO_ERROR) {
153	            return st;
154	        }
155	        st = CreateMatmulOutAclnnTensor();
156	        if (st != NO_ERROR) {
157	            return st;
158	        }
159	    }
160	    return NO_ERROR;
161	}
162	
163	aclnnStatus LinearAclnnRunner::SetAclNNWorkspaceExecutor()
164	{
165	    ATB_LOG(INFO) << GetLogPrefix() << "LinearAclnnRunner::SetAclNNWorkspaceExecutor";
166	    if (isWeightNz_) {
167	        if (param_.hasBias) {
168	            return SetAclnnAddmmWeightNzWorkspaceExecutor();
169	        } else {
170	            if (isBatch_) {
171	                return SetAclnnBatchMatMulWeightNzWorkspaceExecutor();
172	            } else {
173	                return SetAclnnMatmulWeightNzWorkspaceExecutor();
174	            }
175	        }
176	    } else {
177	        if (param_.hasBias) {
178	            return SetAclnnAddmmWorkspaceExecutor();
179	        } else {
180	            return SetAclnnMatmulWorkspaceExecutor();
181	        }
182	    }
183	}
184	
185	Status LinearAclnnRunner::LaunchAclnnKernel()
186	{
187	    ATB_LOG(INFO) << GetLogPrefix() << "LinearAclnnRunner::LaunchAclnnKernel";
188	
189	    aclrtStream executeStream = GetExecuteStream(atbVariantPack_.context);
190	
191	    aclnnStatus ret = ACL_SUCCESS;
192	    if (isWeightNz_) {
193	        if (param_.hasBias) {
194	            ret = aclnnAddmmWeightNzExecuteFunc_(atbVariantPack_.workspaceBuffer, atbVariantPack_.workspaceBufferSize,
195	                                                 aclnnExecutor_.get(), executeStream);
196	        } else {
197	            if (isBatch_) {
198	                ret = aclnnBatchMatMulWeightNzExecuteFunc_(atbVariantPack_.workspaceBuffer,
199	                                                           atbVariantPack_.workspaceBufferSize, aclnnExecutor_.get(),
200	                                                           executeStream);
201	            } else {
202	                ret = aclnnMatmulWeightNzExecuteFunc_(atbVariantPack_.workspaceBuffer,
203	                                                      atbVariantPack_.workspaceBufferSize, aclnnExecutor_.get(),
204	                                                      executeStream);
205	            }
206	        }
207	    } else {
208	        if (param_.hasBias) {
209	            ret = aclnnAddmmExecuteFunc_(atbVariantPack_.workspaceBuffer, atbVariantPack_.workspaceBufferSize,
210	                                         aclnnExecutor_.get(), executeStream);
211	        } else {
212	            ret = aclnnMatmulExecuteFunc_(atbVariantPack_.workspaceBuffer, atbVariantPack_.workspaceBufferSize,
213	                                          aclnnExecutor_.get(), executeStream);
214	        }
215	    }
216	    if (ret != ACL_SUCCESS) {
217	        ATB_LOG(ERROR) << GetLogPrefix() << "Atb aclnn op kernel launch failed with return value: " << ret;
218	        return ERROR_CANN_ERROR;
219	    }
220	    ATB_LOG(INFO) << GetLogPrefix() << "LaunchAclnnKernel execute success.";
221	    return NO_ERROR;
222	}
223	
224	void LinearAclnnRunner::GetTensorNum()
225	{
226	    if (param_.hasBias) {
227	        aclInTensorNum_ = 3; // 3: self, mat1, mat2
228	    } else {
229	        aclInTensorNum_ = 2; // 2: self, mat2
230	    }
231	    aclOutTensorNum_ = 1;
232	}
233	
234	void LinearAclnnRunner::InitTensorIndex()
235	{
236	    atbInTensorIndex_ = 0;
237	    aclInTensorIndex_ = 0;
238	    atbOutTensorIndex_ = 0;
239	    aclOutTensorIndex_ = 0;
240	    matmulSelfAclTensorIndex_ = 0;
241	    matmulMat2AclTensorIndex_ = 0;
242	    matmulOutAclTensorIndex_ = 0;
243	    addmmSelfAclTensorIndex_ = 0;
244	    addmmMat1AclTensorIndex_ = 0;
245	    addmmMat2AclTensorIndex_ = 0;
246	    addmmOutAclTensorIndex_ = 0;
247	}
248	
249	Status LinearAclnnRunner::CreateMatmulSelfAclnnTensor()
250	{
251	    ATB_LOG(INFO) << "LinearAclnnRunner::CreateMatmulSelfAclnnTensor";
252	
253	    std::shared_ptr<AclNNTensor> aclnnTensorPtr = CreateXAclnnTensor(MATMUL_SELF_ACLNN_TENSOR_IDX);
254	    if (!aclnnTensorPtr->tensor) {
255	        ATB_LOG(ERROR) << GetLogPrefix() << "matmul self aclCreateTensor failed";
256	        return ERROR_INTERNAL_ERROR;
257	    }
258	    aclnnVariantPack_.aclInTensors.at(aclInTensorIndex_) = aclnnTensorPtr;
259	    matmulSelfAclTensorIndex_ = aclInTensorIndex_++;
260	    return NO_ERROR;
261	}
262	
263	Status LinearAclnnRunner::CreateMatmulMat2AclnnTensor()
264	{
265	    ATB_LOG(INFO) << "LinearAclnnRunner::CreateMatmulMat2AclnnTensor";
266	
267	    std::shared_ptr<AclNNTensor> aclnnTensorPtr = isWeightNz_ ?
268	                                                      CreateWeightNzAclnnTensor(MATMUL_MAT2_ACLNN_TENSOR_IDX) :
269	                                                      CreateWeightAclnnTensor(MATMUL_MAT2_ACLNN_TENSOR_IDX);
270	    if (!aclnnTensorPtr->tensor) {
271	        ATB_LOG(ERROR) << GetLogPrefix() << "matmul mat2 aclCreateTensor failed";
272	        return ERROR_INTERNAL_ERROR;
273	    }
274	    aclnnVariantPack_.aclInTensors.at(aclInTensorIndex_) = aclnnTensorPtr;
275	    matmulMat2AclTensorIndex_ = aclInTensorIndex_++;
276	    return NO_ERROR;
277	}
278	
279	Status LinearAclnnRunner::CreateMatmulOutAclnnTensor()
280	{
281	    ATB_LOG(INFO) << "LinearAclnnRunner::CreateMatmulOutAclnnTensor";
282	
283	    std::shared_ptr<AclNNTensor> aclnnTensorPtr = CreateOutputAclnnTensor(MATMUL_OUT_ACLNN_TENSOR_IDX);
284	    if (!aclnnTensorPtr->tensor) {
285	        ATB_LOG(ERROR) << GetLogPrefix() << "matmul out aclCreateTensor failed";
286	        return ERROR_INTERNAL_ERROR;
287	    }
288	    aclnnVariantPack_.aclOutTensors.at(aclOutTensorIndex_) = aclnnTensorPtr;
289	    matmulOutAclTensorIndex_ = aclOutTensorIndex_++;
290	    return NO_ERROR;
291	}
292	
293	Status LinearAclnnRunner::CreateAddmmSelfAclnnTensor()
294	{
295	    ATB_LOG(INFO) << "LinearAclnnRunner::CreateAddmmSelfAclnnTensor";
296	
297	    std::shared_ptr<AclNNTensor> aclnnTensorPtr = CreateBiasAclnnTensor(ADDMM_SELF_ACLNN_TENSOR_IDX);
298	    if (!aclnnTensorPtr->tensor) {
299	        ATB_LOG(ERROR) << GetLogPrefix() << "addmm self aclCreateTensor failed";
300	        return ERROR_INTERNAL_ERROR;
301	    }
302	    aclnnVariantPack_.aclInTensors.at(aclInTensorIndex_) = aclnnTensorPtr;
303	    addmmSelfAclTensorIndex_ = aclInTensorIndex_++;
304	    return NO_ERROR;
305	}
306	
307	Status LinearAclnnRunner::CreateAddmmMat1AclnnTensor()
308	{
309	    ATB_LOG(INFO) << "LinearAclnnRunner::CreateAddmmMat1AclnnTensor";
310	
311	    std::shared_ptr<AclNNTensor> aclnnTensorPtr = CreateXAclnnTensor(ADDMM_MAT1_ACLNN_TENSOR_IDX);
312	    if (!aclnnTensorPtr->tensor) {
313	        ATB_LOG(ERROR) << GetLogPrefix() << "addmm mat1 aclCreateTensor failed";
314	        return ERROR_INTERNAL_ERROR;
315	    }
316	    aclnnVariantPack_.aclInTensors.at(aclInTensorIndex_) = aclnnTensorPtr;
317	    addmmMat2AclTensorIndex_ = aclInTensorIndex_++;
318	    return NO_ERROR;
319	}
320	
321	Status LinearAclnnRunner::CreateAddmmMat2AclnnTensor()
322	{
323	    ATB_LOG(INFO) << "LinearAclnnRunner::CreateAddmmMat2AclnnTensor";
324	
325	    std::shared_ptr<AclNNTensor> aclnnTensorPtr = isWeightNz_ ? CreateWeightNzAclnnTensor(ADDMM_MAT2_ACLNN_TENSOR_IDX) :
326	                                                                CreateWeightAclnnTensor(ADDMM_MAT2_ACLNN_TENSOR_IDX);
327	    if (!aclnnTensorPtr->tensor) {
328	        ATB_LOG(ERROR) << GetLogPrefix() << "addmm mat2 aclCreateTensor failed";
329	        return ERROR_INTERNAL_ERROR;
330	    }
331	    aclnnVariantPack_.aclInTensors.at(aclInTensorIndex_) = aclnnTensorPtr;
332	    addmmMat2AclTensorIndex_ = aclInTensorIndex_++;
333	    return NO_ERROR;
334	}
335	
336	Status LinearAclnnRunner::CreateAddmmOutAclnnTensor()
337	{
338	    ATB_LOG(INFO) << "LinearAclnnRunner::CreateAddmmOutAclnnTensor";
339	
340	    std::shared_ptr<AclNNTensor> aclnnTensorPtr = CreateOutputAclnnTensor(ADDMM_OUT_ACLNN_TENSOR_IDX);
341	    if (!aclnnTensorPtr->tensor) {
342	        ATB_LOG(ERROR) << GetLogPrefix() << "addmm out aclCreateTensor failed";
343	        return ERROR_INTERNAL_ERROR;
344	    }
345	    aclnnVariantPack_.aclOutTensors.at(aclOutTensorIndex_) = aclnnTensorPtr;
346	    addmmOutAclTensorIndex_ = aclOutTensorIndex_++;
347	    return NO_ERROR;
348	}
349	
350	aclnnStatus LinearAclnnRunner::SetAclnnMatmulWorkspaceExecutor()
351	{
352	    ATB_LOG(INFO) << "LinearAclnnRunner::SetAclnnMatmulWorkspaceExecutor";
353	
354	    aclTensor *self = aclnnVariantPack_.aclInTensors.at(matmulSelfAclTensorIndex_)->tensor;
355	    aclTensor *mat2 = aclnnVariantPack_.aclInTensors.at(matmulMat2AclTensorIndex_)->tensor;
356	    aclTensor *out = aclnnVariantPack_.aclOutTensors.at(matmulOutAclTensorIndex_)->tensor;
357	
358	    int8_t cubeMathType = 1;
359	    aclOpExecutor *rawExecutePtr = aclnnExecutor_.get();
360	
361	    aclnnStatus ret = aclnnMatmulGetWorkspaceSizeFunc_(self, mat2, out, cubeMathType,
362	                                                       &(atbVariantPack_.workspaceBufferSize), &rawExecutePtr);
363	    aclnnExecutor_ = std::shared_ptr<aclOpExecutor>(rawExecutePtr, [this](aclOpExecutor *ptr) {
364	        if (ptr && executorRepeatable_) {
365	            aclDestroyAclOpExecutor(ptr);
366	        }
367	    });
368	    return ret;
369	}
370	
371	aclnnStatus LinearAclnnRunner::SetAclnnAddmmWorkspaceExecutor()
372	{
373	    ATB_LOG(INFO) << "LinearAclnnRunner::SetAclnnAddmmWorkspaceExecutor";
374	
375	    aclTensor *self = aclnnVariantPack_.aclInTensors.at(addmmSelfAclTensorIndex_)->tensor;
376	    aclTensor *mat1 = aclnnVariantPack_.aclInTensors.at(addmmMat1AclTensorIndex_)->tensor;
377	    aclTensor *mat2 = aclnnVariantPack_.aclInTensors.at(addmmMat2AclTensorIndex_)->tensor;
378	    aclTensor *out = aclnnVariantPack_.aclOutTensors.at(addmmOutAclTensorIndex_)->tensor;
379	
380	    if (alpha_) {
381	        if (aclDestroyScalar(alpha_) != ACL_SUCCESS) {
382	            ATB_LOG(ERROR) << GetLogPrefix() << "alpha aclDestroyScalar error";
383	            return ERROR_INTERNAL_ERROR;
384	        }
385	        alpha_ = nullptr;
386	    }
387	    if (beta_) {
388	        if (aclDestroyScalar(beta_) != ACL_SUCCESS) {
389	            ATB_LOG(ERROR) << GetLogPrefix() << "beta aclDestroyScalar error";
390	            return ERROR_INTERNAL_ERROR;
391	        }
392	        beta_ = nullptr;
393	    }
394	
395	    float alphaValue = 1.0f;
396	    alpha_ = aclCreateScalar(&alphaValue, aclDataType::ACL_FLOAT);
397	    float betaValue = 1.0f;
398	    beta_ = aclCreateScalar(&betaValue, aclDataType::ACL_FLOAT);
399	    int8_t cubeMathType = 1;
400	    aclOpExecutor *rawExecutePtr = aclnnExecutor_.get();
401	
402	    aclnnStatus ret = aclnnAddmmGetWorkspaceSizeFunc_(self, mat1, mat2, beta_, alpha_, out, cubeMathType,
403	                                                      &(atbVariantPack_.workspaceBufferSize), &rawExecutePtr);
404	    aclnnExecutor_ = std::shared_ptr<aclOpExecutor>(rawExecutePtr, [this](aclOpExecutor *ptr) {
405	        if (ptr && executorRepeatable_) {
406	            aclDestroyAclOpExecutor(ptr);
407	        }
408	    });
409	    return ret;
410	}
411	
412	aclnnStatus LinearAclnnRunner::SetAclnnMatmulWeightNzWorkspaceExecutor()
413	{
414	    ATB_LOG(INFO) << "LinearAclnnRunner::SetAclnnMatmulWeightNzWorkspaceExecutor";
415	
416	    aclTensor *self = aclnnVariantPack_.aclInTensors.at(matmulSelfAclTensorIndex_)->tensor;
417	    aclTensor *mat2 = aclnnVariantPack_.aclInTensors.at(matmulMat2AclTensorIndex_)->tensor;
418	    aclTensor *out = aclnnVariantPack_.aclOutTensors.at(matmulOutAclTensorIndex_)->tensor;
419	
420	    int8_t cubeMathType = 1;
421	    aclOpExecutor *rawExecutePtr = aclnnExecutor_.get();
422	
423	    aclnnStatus ret = aclnnMatmulWeightNzGetWorkspaceSizeFunc_(self, mat2, out, cubeMathType,
424	                                                               &(atbVariantPack_.workspaceBufferSize), &rawExecutePtr);
425	    aclnnExecutor_ = std::shared_ptr<aclOpExecutor>(rawExecutePtr, [this](aclOpExecutor *ptr) {
426	        if (ptr && executorRepeatable_) {
427	            aclDestroyAclOpExecutor(ptr);
428	        }
429	    });
430	    return ret;
431	}
432	
433	aclnnStatus LinearAclnnRunner::SetAclnnAddmmWeightNzWorkspaceExecutor()
434	{
435	    ATB_LOG(INFO) << "LinearAclnnRunner::SetAclnnAddmmWeightNzWorkspaceExecutor";
436	
437	    aclTensor *self = aclnnVariantPack_.aclInTensors.at(addmmSelfAclTensorIndex_)->tensor;
438	    aclTensor *mat1 = aclnnVariantPack_.aclInTensors.at(addmmMat1AclTensorIndex_)->tensor;
439	    aclTensor *mat2 = aclnnVariantPack_.aclInTensors.at(addmmMat2AclTensorIndex_)->tensor;
440	    aclTensor *out = aclnnVariantPack_.aclOutTensors.at(addmmOutAclTensorIndex_)->tensor;
441	
442	    if (alpha_) {
443	        if (aclDestroyScalar(alpha_) != ACL_SUCCESS) {
444	            ATB_LOG(ERROR) << GetLogPrefix() << "alpha aclDestroyScalar error";
445	            return ERROR_INTERNAL_ERROR;
446	        }
447	        alpha_ = nullptr;
448	    }
449	    if (beta_) {
450	        if (aclDestroyScalar(beta_) != ACL_SUCCESS) {
451	            ATB_LOG(ERROR) << GetLogPrefix() << "beta aclDestroyScalar error";
452	            return ERROR_INTERNAL_ERROR;
453	        }
454	        beta_ = nullptr;
455	    }
456	
457	    float alphaValue = 1.0f;
458	    alpha_ = aclCreateScalar(&alphaValue, aclDataType::ACL_FLOAT);
459	    float betaValue = 1.0f;
460	    beta_ = aclCreateScalar(&betaValue, aclDataType::ACL_FLOAT);
461	    int8_t cubeMathType = 1;
462	    aclOpExecutor *rawExecutePtr = aclnnExecutor_.get();
463	
464	    aclnnStatus ret = aclnnAddmmWeightNzGetWorkspaceSizeFunc_(self, mat1, mat2, beta_, alpha_, out, cubeMathType,
465	                                                              &(atbVariantPack_.workspaceBufferSize), &rawExecutePtr);
466	    aclnnExecutor_ = std::shared_ptr<aclOpExecutor>(rawExecutePtr, [this](aclOpExecutor *ptr) {
467	        if (ptr && executorRepeatable_) {
468	            aclDestroyAclOpExecutor(ptr);
469	        }
470	    });
471	    return ret;
472	}
473	
474	aclnnStatus LinearAclnnRunner::SetAclnnBatchMatMulWeightNzWorkspaceExecutor()
475	{
476	    ATB_LOG(INFO) << "LinearAclnnRunner::SetAclnnBatchMatMulWeightNzWorkspaceExecutor";
477	
478	    aclTensor *self = aclnnVariantPack_.aclInTensors.at(matmulSelfAclTensorIndex_)->tensor;
479	    aclTensor *mat2 = aclnnVariantPack_.aclInTensors.at(matmulMat2AclTensorIndex_)->tensor;
480	    aclTensor *out = aclnnVariantPack_.aclOutTensors.at(matmulOutAclTensorIndex_)->tensor;
481	
482	    int8_t cubeMathType = 1;
483	    aclOpExecutor *rawExecutePtr = aclnnExecutor_.get();
484	
485	    aclnnStatus ret = aclnnBatchMatMulWeightNzGetWorkspaceSizeFunc_(
486	        self, mat2, out, cubeMathType, &(atbVariantPack_.workspaceBufferSize), &rawExecutePtr);
487	    aclnnExecutor_ = std::shared_ptr<aclOpExecutor>(rawExecutePtr, [this](aclOpExecutor *ptr) {
488	        if (ptr && executorRepeatable_) {
489	            aclDestroyAclOpExecutor(ptr);
490	        }
491	    });
492	    return ret;
493	}
