495	std::shared_ptr<AclNNTensor> LinearAclnnRunner::CreateXAclnnTensor(int aclnnTensorIndex)
496	{
497	    Tensor atbTensor = atbVariantPack_.inTensors.at(atbInTensorIndex_++);
498	    std::shared_ptr<AclNNTensor> aclnnTensorPtr = InitAclnnTensor(atbTensor, aclnnTensorIndex);
499	    Dims viewShape = atbTensor.desc.shape;
500	    if (viewShape.dimNum == 3 && !isBatch_) {
501	        viewShape.dims[0] = viewShape.dims[0] * viewShape.dims[1];
502	        viewShape.dims[1] = viewShape.dims[2];
503	        viewShape.dimNum = 2;
504	    }
505	    aclnnTensorPtr->strides = GetCopyTensorStride(viewShape);
506	    if (param_.transposeA) {
507	        int64_t m = viewShape.dims[viewShape.dimNum - 1];
508	        int64_t k = viewShape.dims[viewShape.dimNum - 2];
509	        viewShape.dims[viewShape.dimNum - 2] = m;
510	        viewShape.dims[viewShape.dimNum - 1] = k;
511	        int64_t lastStride = aclnnTensorPtr->strides[viewShape.dimNum - 1];
512	        aclnnTensorPtr->strides[viewShape.dimNum - 1] = aclnnTensorPtr->strides[viewShape.dimNum - 2];
513	        aclnnTensorPtr->strides[viewShape.dimNum - 2] = lastStride;
514	    }
515	    aclnnTensorPtr->tensor = aclCreateTensor(
516	        viewShape.dims, viewShape.dimNum, atbTensor.desc.dtype, aclnnTensorPtr->strides.data(), 0,
517	        atbTensor.desc.format, atbTensor.desc.shape.dims, atbTensor.desc.shape.dimNum, atbTensor.deviceData);
518	    return aclnnTensorPtr;
519	}
