530	        viewShape.dims[viewShape.dimNum - 2] = k;
531	        viewShape.dims[viewShape.dimNum - 1] = n;
532	        int64_t lastStride = aclnnTensorPtr->strides[viewShape.dimNum - 1];
533	        aclnnTensorPtr->strides[viewShape.dimNum - 1] = aclnnTensorPtr->strides[viewShape.dimNum - 2];
534	        aclnnTensorPtr->strides[viewShape.dimNum - 2] = lastStride;
