542	std::shared_ptr<AclNNTensor> LinearAclnnRunner::CreateWeightNzAclnnTensor(int aclnnTensorIndex)
543	{
544	    Tensor atbTensor = atbVariantPack_.inTensors.at(atbInTensorIndex_++);
545	    std::shared_ptr<AclNNTensor> aclnnTensorPtr = InitAclnnTensor(atbTensor, aclnnTensorIndex);
546	    Dims viewShape = atbTensor.desc.shape;
547	    Dims storageShape = atbTensor.desc.shape;
548	    if (viewShape.dimNum == 4) {
549	        Dims oldShape = viewShape;
550	        if (isBatch_) {
551	            viewShape.dims[0] = oldShape.dims[0];
552	            viewShape.dims[1] = oldShape.dims[2];
553	            viewShape.dims[2] = oldShape.dims[1] * oldShape.dims[3];
554	            viewShape.dimNum = 3;
555	            ATB_LOG(INFO) << GetLogPrefix() << "viewShape: [" << viewShape.dims[0] << ", " << viewShape.dims[1] << ", "
556	                          << viewShape.dims[2] << "]";
557	        } else {
558	            viewShape.dims[0] = oldShape.dims[2];
559	            viewShape.dims[1] = oldShape.dims[1] * oldShape.dims[3];
560	            viewShape.dimNum = 2;
561	            ATB_LOG(INFO) << GetLogPrefix() << "viewShape: [" << viewShape.dims[0] << ", " << viewShape.dims[1] << "]";
562	        }
563	    }
564	    aclnnTensorPtr->strides = GetCopyTensorStride(viewShape);
565	    if (param_.transposeB) {
566	        int64_t k = viewShape.dims[viewShape.dimNum - 1];
567	        int64_t n = viewShape.dims[viewShape.dimNum - 2];
568	        viewShape.dims[viewShape.dimNum - 2] = k;
569	        viewShape.dims[viewShape.dimNum - 1] = n;
570	        int64_t lastStride = aclnnTensorPtr->strides[viewShape.dimNum - 1];
571	        aclnnTensorPtr->strides[viewShape.dimNum - 1] = aclnnTensorPtr->strides[viewShape.dimNum - 2];
572	        aclnnTensorPtr->strides[viewShape.dimNum - 2] = lastStride;
573	    }
574	    if (storageShape.dimNum == 2) {
575	        Dims oldShape = storageShape;
576	        storageShape.dims[0] = UtilsInternal::AlignUp(oldShape.dims[1], DEFAULT_ALIGN) / DEFAULT_ALIGN;
577	        storageShape.dims[1] = UtilsInternal::AlignUp(oldShape.dims[0], DEFAULT_ALIGN) / DEFAULT_ALIGN;
578	        storageShape.dims[2] = DEFAULT_ALIGN;
579	        storageShape.dims[3] = DEFAULT_ALIGN;
580	        storageShape.dimNum = 4;
581	        ATB_LOG(INFO) << GetLogPrefix() << "storageShape: [" << storageShape.dims[0] << ", " << storageShape.dims[1]
582	                      << ", " << storageShape.dims[2] << ", " << storageShape.dims[3] << "]";
583	    } else if (storageShape.dimNum == 3) {
584	        Dims oldShape = storageShape;
585	        storageShape.dims[0] = oldShape.dims[0];
586	        storageShape.dims[1] = UtilsInternal::AlignUp(oldShape.dims[2], DEFAULT_ALIGN) / DEFAULT_ALIGN;
587	        storageShape.dims[2] = UtilsInternal::AlignUp(oldShape.dims[1], DEFAULT_ALIGN) / DEFAULT_ALIGN;
588	        storageShape.dims[3] = DEFAULT_ALIGN;
589	        storageShape.dims[4] = DEFAULT_ALIGN;
590	        storageShape.dimNum = 5;
591	        ATB_LOG(INFO) << GetLogPrefix() << "storageShape: [" << storageShape.dims[0] << ", " << storageShape.dims[1]
592	                      << ", " << storageShape.dims[2] << ", " << storageShape.dims[3] << ", " << storageShape.dims[4]
593	                      << "]";
594	    } else if (storageShape.dimNum == 4) {
595	        if (isBatch_) {
596	            Dims oldShape = storageShape;
597	            storageShape.dims[0] = oldShape.dims[0];
598	            storageShape.dims[1] = oldShape.dims[1];
599	            storageShape.dims[2] = UtilsInternal::AlignUp(oldShape.dims[2], DEFAULT_ALIGN) / DEFAULT_ALIGN;
600	            storageShape.dims[3] = DEFAULT_ALIGN;
601	            storageShape.dims[4] = DEFAULT_ALIGN;
602	            storageShape.dimNum = 5;
603	            ATB_LOG(INFO) << GetLogPrefix() << "storageShape: [" << storageShape.dims[0] << ", " << storageShape.dims[1]
604	                          << ", " << storageShape.dims[2] << ", " << storageShape.dims[3] << ", "
605	                          << storageShape.dims[4] << "]";
606	        } else {
607	            Dims oldShape = storageShape;
608	            storageShape.dims[0] = oldShape.dims[1];
609	            storageShape.dims[1] = UtilsInternal::AlignUp(oldShape.dims[2], DEFAULT_ALIGN) / DEFAULT_ALIGN;
610	            storageShape.dims[2] = DEFAULT_ALIGN;
611	            storageShape.dims[3] = DEFAULT_ALIGN;
612	            storageShape.dimNum = 4;
613	            ATB_LOG(INFO) << GetLogPrefix() << "storageShape: [" << storageShape.dims[0] << ", " << storageShape.dims[1]
614	                          << ", " << storageShape.dims[2] << ", " << storageShape.dims[3] << "]";
615	        }
616	    }
617	    aclnnTensorPtr->tensor =
618	        aclCreateTensor(viewShape.dims, viewShape.dimNum, atbTensor.desc.dtype, aclnnTensorPtr->strides.data(), 0,
619	                        atbTensor.desc.format, storageShape.dims, storageShape.dimNum, atbTensor.deviceData);
620	    return aclnnTensorPtr;
621	}
