48	Status AclnnRunner::SetupImpl(RunnerVariantPack &runnerVariantPack)
49	{
50	    ATB_LOG(INFO) << GetLogPrefix() << "aclnn runner setupImpl";
51	    if (!runnerVariantPack.context) {
52	        ATB_LOG(ERROR) << GetLogPrefix() << "context is not ContextBase, setup fail";
53	        return ERROR_INVALID_CONTEXT_ADDR;
54	    }
55	    Status ret = NO_ERROR;
56	    const std::string &opName = this->GetName();
57	    AclnnCacheSlot aclnnCacheSlot = {};
58	    // executorCache hit
59	    if (executorRepeatable_ &&
60	        GetSingleton<AclnnExecutorCache>().FetchCacheSlot(opName, runnerVariantPack, aclnnCacheSlot) == NO_ERROR) {
61	        if (!IsAclnnRunnerVariankPackEqual(this->aclnnVariantPack_, runnerVariantPack)) {
62	            ATB_LOG(INFO) << GetLogPrefix()
63	                          << "fetched cached runnerVariantPack not same as aclnnVariantPack_, build again";
64	            ret = BuildAclnnVariantPack(runnerVariantPack);
65	            if (ret != NO_ERROR) {
66	                ATB_LOG(ERROR) << GetLogPrefix() << "BuildAclnnVariantPack failed!";
67	                return ret;
68	            }
69	        }
70	        this->atbVariantPack_.workspaceBufferSize = aclnnCacheSlot.workspaceSize;
71	        this->aclnnExecutor_ = aclnnCacheSlot.executor;
72	        return NO_ERROR;
73	    }
74	    // cache miss，创建新的executor
75	    ATB_LOG(INFO) << GetLogPrefix() << "ExecutorCache miss, BuildAclnnVariantPack directly";
76	    ret = BuildAclnnVariantPack(runnerVariantPack);
77	    if (ret != NO_ERROR) {
78	        ATB_LOG(ERROR) << GetLogPrefix() << "BuildAclnnVariantPack failed!";
79	        return ret;
80	    }
81	    aclnnStatus aclnnRet = ACL_SUCCESS;
82	    aclnnRet = SetAclNNWorkspaceExecutor();
83	    if (aclnnRet != ACL_SUCCESS) {
84	        ATB_LOG(ERROR) << GetLogPrefix() << "Atb aclnn op set workspace failed with return value: " << aclnnRet;
85	        return ERROR_CANN_ERROR;
86	    }
87	    ATB_LOG(INFO) << GetLogPrefix() << "getWorkspaceSize success, workspaceSize: " << this->atbVariantPack_.workspaceBufferSize;
88	    if (!useCache()) {
89	        return ret;
90	    }
91	    aclnnRet = aclSetAclOpExecutorRepeatable(this->aclnnExecutor_.get());
92	    if (aclnnRet != 0) {
93	        // 设置算子可复用失败，标记cache中executor不可复用
94	        ATB_LOG(INFO) << this->GetName() << " call aclSetAclOpExecutorRepeatable fail with error code: " << aclnnRet;
95	        this->executorRepeatable_ = false;
96	    } else {
97	        // 设置算子可复用成功，标记cache中executor可复用
98	        ATB_LOG(INFO) << this->GetName() << " call aclSetAclOpExecutorRepeatable success: ";
99	        this->executorRepeatable_ = true;
100	    }
101	    aclnnCacheSlot = {this->atbVariantPack_.workspaceBufferSize, aclnnExecutor_};
102	    ret = GetSingleton<AclnnExecutorCache>().AddCacheSlot(opName, runnerVariantPack, aclnnCacheSlot);
103	    if (ret != NO_ERROR) {
104	        ATB_LOG(ERROR) << GetLogPrefix() << "AclnnExecutorCache update cache failed!";
105	    }
106	    ATB_LOG(INFO) << GetLogPrefix() << "AclnnExecutorCache AddCacheSlot success opName: " << opName
107	                  << ", runnerVariantPack: " << runnerVariantPack.ToString();
108	    return ret;
109	}
