116	Status AclnnRunner::PreExecuteImpl(RunnerVariantPack &runnerVariantPack)
117	{
118	    ATB_LOG(INFO) << GetLogPrefix() << "AclNNOpCacheUpdateAclNNVariantPack";
119	    aclnnStatus ret = ACL_SUCCESS;
120	    for (size_t i = 0; i < this->aclnnVariantPack_.aclInTensors.size(); ++i) {
121	        // 部分场景中存在aclnn接口使用空tensor占位最后可选tensor，但是runnerVariantPack中不存放tensor的情况，可以跳过
122	        if (i >= runnerVariantPack.inTensors.size()) {
123	            break;
124	        }
125	        if (this->aclnnVariantPack_.aclInTensors[i] == nullptr ||
126	            !this->aclnnVariantPack_.aclInTensors[i]->needUpdateTensorDataPtr) {
127	            continue;
128	        }
129	        this->aclnnVariantPack_.aclInTensors[i]->atbTensor = runnerVariantPack.inTensors.at(i);
130	        if (this->aclnnVariantPack_.aclInTensors[i]->tensorListidx == AclNNTensor::notInTensorList) {
131	            ret = aclSetInputTensorAddr(this->aclnnExecutor_.get(), this->aclnnVariantPack_.aclInTensors[i]->tensorIdx,
132	                                        this->aclnnVariantPack_.aclInTensors[i]->tensor,
133	                                        this->aclnnVariantPack_.aclInTensors[i]->atbTensor.deviceData);
134	        } else {
135	            ret = aclSetDynamicInputTensorAddr(
136	                this->aclnnExecutor_.get(), this->aclnnVariantPack_.aclInTensors[i]->tensorListidx,
137	                this->aclnnVariantPack_.aclInTensors[i]->tensorIdx,
138	                this->aclnnVariantPack_.aclInTensorList[this->aclnnVariantPack_.aclInTensors[i]->tensorListidx],
139	                this->aclnnVariantPack_.aclInTensors[i]->atbTensor.deviceData);
140	        }
141	        if (ret != 0) {
142	            ATB_LOG(ERROR) << GetLogPrefix() << "inTensor " << i << " call UpdateAclTensorDataPtr fail, error: " << ret;
143	            return atb::ERROR_CANN_ERROR;
144	        }
145	    }
146	
147	    for (size_t i = 0; i < this->aclnnVariantPack_.aclOutTensors.size(); ++i) {
148	        if (i >= runnerVariantPack.outTensors.size()) {
149	            break;
150	        }
151	        if (this->aclnnVariantPack_.aclOutTensors[i] == nullptr ||
152	            !this->aclnnVariantPack_.aclOutTensors[i]->needUpdateTensorDataPtr) {
153	            continue;
154	        }
155	        this->aclnnVariantPack_.aclOutTensors[i]->atbTensor = runnerVariantPack.outTensors.at(i);
156	        if (this->aclnnVariantPack_.aclOutTensors[i]->tensorListidx == AclNNTensor::notInTensorList) {
157	            ret =
158	                aclSetOutputTensorAddr(this->aclnnExecutor_.get(), this->aclnnVariantPack_.aclOutTensors[i]->tensorIdx,
159	                                       this->aclnnVariantPack_.aclOutTensors[i]->tensor,
160	                                       this->aclnnVariantPack_.aclOutTensors[i]->atbTensor.deviceData);
161	        } else {
162	            ret = aclSetDynamicOutputTensorAddr(
163	                this->aclnnExecutor_.get(), this->aclnnVariantPack_.aclOutTensors[i]->tensorListidx,
164	                this->aclnnVariantPack_.aclOutTensors[i]->tensorIdx,
165	                this->aclnnVariantPack_.aclOutTensorList[this->aclnnVariantPack_.aclOutTensors[i]->tensorListidx],
166	                this->aclnnVariantPack_.aclOutTensors[i]->atbTensor.deviceData);
167	        }
168	        if (ret != 0) {
169	            ATB_LOG(ERROR) << GetLogPrefix() << "outTensor " << i
170	                           << " call UpdateAclTensorDataPtr fail, error: " << ret;
171	            return atb::ERROR_CANN_ERROR;
172	        }
173	    }
174	
175	    return atb::NO_ERROR;
176	}
177	
178	void AclnnRunner::UpdateWorkspace(const RunnerVariantPack &runnerVariantPack)
179	{
180	    this->atbVariantPack_.workspaceBufferSize = runnerVariantPack.workspaceBufferSize;
181	    this->atbVariantPack_.workspaceBuffer = runnerVariantPack.workspaceBuffer;
182	}
